test('starts with initial value and no error', () => {
  const { result } = renderHook(() => useFormField('hello'));
  expect(result.current.value).toBe('hello');
  expect(result.current.error).toBe('');
  expect(result.current.touched).toBe(false);
});

test('onChange sets value and touched', () => {
  const { result } = renderHook(() => useFormField(''));
  act(() => result.current.onChange({ target: { value: 'world' } }));
  expect(result.current.value).toBe('world');
  expect(result.current.touched).toBe(true);
});

test('setError stores an error message', () => {
  const { result } = renderHook(() => useFormField(''));
  act(() => result.current.setError('Required field'));
  expect(result.current.error).toBe('Required field');
});

test('reset clears all state', () => {
  const { result } = renderHook(() => useFormField('init'));
  act(() => result.current.onChange({ target: { value: 'changed' } }));
  act(() => result.current.setError('bad'));
  act(() => result.current.reset());
  expect(result.current.value).toBe('init');
  expect(result.current.error).toBe('');
  expect(result.current.touched).toBe(false);
});

